    r'''// Editing rules for a text field, tested without any UI toolkit.
use weirdnet_text::TextField;

fn main() {
    let mut field = TextField::new();
    for ch in "git".chars() {
        field.replace(None, &ch.to_string()); // typing inserts at the caret
    }
    field.append_selected("hub.com"); // an inline completion, selected
    field.right(); // Right accepts it
    assert_eq!((field.text(), field.cursor()), ("github.com", 10));

    // Backspace removes a whole grapheme cluster, not one byte or code point.
    let mut emoji = TextField::new();
    emoji.replace(None, "hi 👋🏽");
    emoji.backspace();
    assert_eq!(emoji.text(), "hi ");

    // One-line fields turn pasted line breaks into spaces; multiline ones keep them.
    let mut chat = TextField::multiline();
    chat.replace(None, "line one\r\nline two");
    assert_eq!(chat.text(), "line one\nline two");
}
''',
  ),
  'access': Example(
    r'''[dependencies]
weirdnet-access = "0.1.2"''',
    r'''// A public, members-only resource: a member may write (sealed), a stranger must join first.
use weirdnet_access::*;

fn main() -> Result<()> {
    let mut catalog = Catalog::core();
    catalog.add("files.read", "download files", false)?;
    catalog.add("files.write", "upload and change files", false)?;
    catalog.imply("files.write", &["files.read"])?;
    let roles = presets::ranked(&catalog, &["files.write"], &["files.read"])?;

    let settings = Settings { visibility: Visibility::Public, access: Access::Gated };
    // From weirdnet-net: the node cert, the trust list, and `check_presented` on the membership.
    let member = Facts { user: Some("ulf".into()), membership_role: Some("user".into()), ..Default::default() };
    assert!(matches!(decide(&catalog, &roles, settings, &member, "files.write"), Decision::Allow { transport: Transport::Sealed, .. }));
    let stranger = Facts { user: Some("someone".into()), ..Default::default() };
    assert_eq!(decide(&catalog, &roles, settings, &stranger, "files.read"), Decision::JoinFirst);
    Ok(())
}
''',
  ),
  'push': Example(
    r'''[dependencies]
weirdnet-push = "0.1.1"''',
    r'''// A sender seals a 96-byte wake for a device; only the device can open it, once.
use std::time::Duration;
use weirdnet_push::{PushKey, Reason, ReplayGuard, WakeHandle, wake};

fn main() -> weirdnet_push::Result<()> {
    let key = PushKey::generate(); // stays on the device
    let handle = WakeHandle::generate(); // shared, sealed, with the home relay and trusted peers

    let payload = wake::seal(&key.public(), &handle, Reason::MessageWaiting)?; // a sender
    let w = key.open(&handle, &payload)?; // the device
    let mut guard = ReplayGuard::new(Duration::from_secs(300), 1024);
    guard.check_now(&w)?;
    assert!(guard.check_now(&w).is_err()); // the same wake again is refused
    Ok(())
}
''',
